/// The twelve group colors (docs/design/README.md §2.2). Each has five tints: the free-count scale in the group
/// calendar, where tint 5 is also the group's representative color and is the same in both appearances.
public enum GroupColor: String, CaseIterable, Sendable {
    case tomato
    case tangerine
    case mustard
    case olive
    case forest
    case mint
    case sky
    case sea
    case grape
    case plum
    case blossom
    case cocoa

    /// The Korean name the group settings show.
    public var name: String {
        switch self {
        case .tomato: "토마토"
        case .tangerine: "귤"
        case .mustard: "겨자"
        case .olive: "올리브"
        case .forest: "숲"
        case .mint: "민트"
        case .sky: "하늘"
        case .sea: "바다"
        case .grape: "포도"
        case .plum: "자두"
        case .blossom: "벚꽃"
        case .cocoa: "코코아"
        }
    }

    /// The tint for a level from 1 to 5. Level 0 is the empty cell, `GeunalColor.emptyCell`.
    public func tint(_ level: Int) -> Color {
        precondition((1...5).contains(level), "tint levels run from 1 to 5")
        let ramp = Self.ramps[self]!
        return Color(light: ramp[level - 1].light, dark: ramp[level - 1].dark)
    }

    /// The representative color: tint 5, with white text above 4.6:1.
    public var representative: Color { tint(5) }

    /// Maps how many of a group's `total` members are free to a tint level (docs/design/tokens.json `freeCount`):
    /// nobody is the empty cell (0), everybody is 5, and the rest spread over 1 to 4.
    public static func level(free: Int, of total: Int) -> Int {
        precondition(total >= 1 && (0...total).contains(free), "free must be between 0 and total")
        if free == 0 { return 0 }
        if free == total { return 5 }
        return min(4, 1 + (free - 1) * 4 / (total - 1))
    }

