extension Color {
    /// A color from two sRGB hex values, picked by the current appearance.
    public init(light: UInt32, dark: UInt32) {
        self.init(
            uiColor: UIColor { traits in
                UIColor(rgb: traits.userInterfaceStyle == .dark ? dark : light)
            })
    }
}

extension UIColor {
    fileprivate convenience init(rgb: UInt32) {
        self.init(
            red: CGFloat((rgb >> 16) & 0xFF) / 255,
            green: CGFloat((rgb >> 8) & 0xFF) / 255,
            blue: CGFloat(rgb & 0xFF) / 255,
            alpha: 1)
    }
}

/// The type scale (docs/design/README.md §3). Pretendard comes with M1; until then the system font carries the
/// sizes and weights, scaled with the user's text size through the text style each step is relative to.
public struct TypeStyle: Sendable, Hashable {
    public enum Weight: Sendable, Hashable {
        case regular
        case semibold

        public var font: Font.Weight {
            switch self {
            case .regular: .regular
            case .semibold: .semibold
            }
        }
    }

    public enum Relative: Sendable, Hashable {
        case largeTitle
        case title
        case title2
        case body
        case subheadline
        case footnote
        case caption2

        public var textStyle: Font.TextStyle {
            switch self {
            case .largeTitle: .largeTitle
            case .title: .title
            case .title2: .title2
            case .body: .body
            case .subheadline: .subheadline
            case .footnote: .footnote
            case .caption2: .caption2
            }
        }
    }

    public let size: CGFloat
    public let weight: Weight
    /// Letter spacing as a fraction of the size.
    public let tracking: CGFloat
    public let relativeTo: Relative

    public static let largeTitle = TypeStyle(size: 32, weight: .semibold, tracking: -0.025, relativeTo: .largeTitle)
    public static let title1 = TypeStyle(size: 26, weight: .semibold, tracking: -0.025, relativeTo: .title)
    public static let title2 = TypeStyle(size: 20, weight: .semibold, tracking: -0.015, relativeTo: .title2)
    public static let bodyStrong = TypeStyle(size: 17, weight: .semibold, tracking: -0.01, relativeTo: .body)
    public static let body = TypeStyle(size: 17, weight: .regular, tracking: -0.01, relativeTo: .body)
    public static let secondary = TypeStyle(size: 15, weight: .regular, tracking: -0.01, relativeTo: .subheadline)
    public static let caption = TypeStyle(size: 13, weight: .regular, tracking: -0.01, relativeTo: .footnote)
    public static let micro = TypeStyle(size: 11, weight: .semibold, tracking: -0.01, relativeTo: .caption2)
}

